import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Recipient recipient;

    function setUp() public { 
        c = new C();
        recipient = new Recipient();
    }

    // fuzz parameters: an array length and arbitrary values; we let fuzzer pick addresses by using the deployed helper's address
    function testFuzz_property(uint8 len, uint256 seed) public {
        // keep length reasonable but >0 to be admissible
        uint256 l = bound(len, 1, 10);

        // build tos and vs arrays of length l
        address[] memory tos = new address[](l);
        uint[] memory vs = new uint[](l);
        for (uint i = 0; i < l; i++) {
            // all calls target our helper contract which always succeeds
            tos[i] = address(recipient);
            // derive some amounts from seed to vary values across fuzz runs
            vs[i] = uint256(keccak256(abi.encodePacked(seed, i)));
        }

        // ensure admissible contract_address: not zero and not self
        address contract_address = address(recipient);
        vm.assume(contract_address != address(0));
        vm.assume(contract_address != address(c));

        // Call transfer and capture its return via try/catch to observe actual boolean return.
        bool ok;
        try c.transfer(contract_address, tos, vs) returns (bool ret) {
            ok = ret;
        } catch {
            // if it reverted, mark as false (but reference should not revert given our helper)
            ok = false;
        }

        // GENERAL ASSERTION: reference implementation always returns true for these admissible inputs
        assertTrue(ok);
    }
}

