    // mimic ERC20-like transferFrom signature so low-level call succeeds
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    // fallback to accept calls by selector as well
    fallback() external payable {
        // do nothing, succeed
    }
}

