    function testFuzz_property(address contract_address, address to, uint256 v) public {
        // keep tos and vs non-empty and equal length; to can be any address
        vm.assume(to != address(0)); // ensure the inner transferFrom target is non-zero for clarity

        address[] memory tos = new address[](1);
        tos[0] = to;
        uint[] memory vs = new uint[](1);
        vs[0] = v;

        // We want to observe whether the call reverts or returns true. According to the reference,
        // calling transfer with contract_address == address(0) should revert because of validAddress modifier.
        // The mutant removed that check, so for some inputs (contract_address == address(0)) it will not revert.

        bool ok;
        try c.transfer(contract_address, tos, vs) returns (bool r) {
            ok = r; // completed and returned a bool
        } catch {
            ok = false; // reverted
        }

        // General rule to assert: if contract_address == address(0), reference MUST revert (so ok==false).
        // This holds for the reference for all inputs; the mutant (which allows zero address) will break it for some input.
