    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: actor is the external caller who invokes c.transfer;
    // toAddr is the recipient passed into the callee's transferFrom; val is the amount value
    function testFuzz_property(address actor, address toAddr, uint256 val) public {
        // admissibility: tos/vs arrays must be non-empty and same length; we will create length-1 arrays
        vm.assume(actor != address(0)); // avoid zero-address EOA for caller
        vm.assume(toAddr != address(0));

        // deploy adversarial helper that records the observed from address when transferFrom is invoked
        Recorder rec = new Recorder();

        // prepare arrays of length 1
        address[] memory tos = new address[](1);
        tos[0] = toAddr;
        uint[] memory vs = new uint[](1);
        // bound val to a reasonable non-zero value space to keep it admissible but still fuzzed
        uint256 amount = bound(val, 1, type(uint256).max);
        vs[0] = amount;

        // fund and prank as actor to call c.transfer
        vm.deal(actor, 1 ether);
        vm.prank(actor);

        // call through c.transfer, passing the recorder's address as the contract_address
        // wrap in try/catch to ensure we observe a boolean outcome if needed
        bool ok;
        try c.transfer(address(rec), tos, vs) {
            ok = true;
        } catch {
            ok = false;
