pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: an array of recipient addresses and an array of uint values.
    // We deploy a helper callee that records whether transferFrom was invoked for particular dsts.
    function testFuzz_property(address[] memory tos, uint256[] memory vs) public {
        // admissible domain: arrays non-empty and equal length
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);

        // deploy helper that records calls
        Recorder rec = new Recorder();

        // call c.transfer with the recorder as the contract_address
        // no Ether needed; the call uses low-level call to recorder which will accept and log
        bool ok;
        try c.transfer(address(rec), tos, vs) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: the reference contract attempts a call for index 0 always
        // We detect that by checking the recorder's recordedCalls for the first tos[0]
        // The reference always made that call, so ok must be true AND recorder saw the first call.
        // However, to make this a universal property that the reference satisfies for ALL inputs,
        // we only assert that if the transfer call succeeded (didn't revert), then the recorder
        // must have noticed a call to index 0. The mutant that skips index 0 can cause the
        // recorder to show no call for index 0 while c.transfer returned true, so the assertion
        // will fail on the mutant for some inputs.

        // single assertion reading c via the recorder behavior (recorder is an external counterparty
        // used by c so observing c's effect on it is permitted). We assert that either the call
        // reverted (ok==false) OR the recorder logged a call for index 0. This is equivalent to
        // saying: when transfer returns successfully, it must have attempted index 0.
        assertTrue(!ok || rec.calledFor(tos[0]));
    }
}

// Minimal helper that records whether transferFrom was invoked with particular dsts.
contract Recorder {
    // mapping of destination address to boolean: was it used in any transferFrom call
    mapping(address => bool) public seen;

    // The low-level call from C uses selector transferFrom(address,address,uint256)
    // We'll implement a fallback that decodes calldata expecting that selector and arguments,
    // and record the 'to' (second address argument) as seen.
    fallback() external payable {
        // calldata layout: 4 bytes selector + ABI-encoded args
        // We expect (address from, address to, uint256 amount)
        if (msg.data.length >= 4 + 32*3) {
            // skip selector
            bytes memory data = msg.data;
            // decode manually: slice after 4
            bytes memory args = new bytes(data.length - 4);
            for (uint i = 4; i < data.length; i++) args[i-4] = data[i];
            // abi.decode requires bytes memory
            (address /*from*/, address to, uint256 /*amt*/) = abi.decode(args, (address, address, uint256));
            seen[to] = true;
        }
        // return success to mimic a successful transferFrom
    }

    // helper view for test to query
    function calledFor(address a) external view returns (bool) {
        return seen[a];
    }
}

