// Minimal adversarial helper that records which indices were invoked via transferFrom calldata decoding
contract Recorder {
    mapping(uint => bool) public called;

    // emulate a recipient contract exposing transferFrom(address,address,uint256)
    // We'll implement a fallback that decodes calldata and records the 'to' parameter position index
    // We encode index by placing it into the 'to' address low bits when building test arrays above.
    // However, simpler: decode calldata to get the third argument (uint256 amount); since C passes tos[i]
    // as the second arg (address) we cannot get index directly. Instead, we detect calls by counting
    // how many times we've been called and mark them sequentially. Because C calls within a single
    // transfer invocation in order i=0.., the k-th call corresponds to index k-1.

    uint public calls;

    fallback() external payable {
        // increment call count and mark that index as called
        uint idx = calls;
        called[idx] = true;
        calls++;
    }

    // helper getter to satisfy the test's read of index 0
    function wasCalled(uint i) external view returns (bool) {
        return called[i];
    }
}

