    C c;
    function setUp() public { c = new C(); }

    // fuzz the target address and an amount; the interesting case is when addr == address(0)
    function testFuzz_property(address callee, uint256 v) public {
        // keep params wide but avoid trivial empty arrays later
        vm.assume(v > 0);

        // Deploy a helper that will revert when called; we will pass its address as the transfer target
        Reverter r = new Reverter();

        address target = callee;
        // allow fuzzer to still pick the zero address; if it picks zero, we use zero (the mutant allows it)
        // else use the reverter to ensure failing external call behavior for most addresses
        if (target == address(0)) {
            // keep target as zero to exercise the mutant's relaxed check
            // nothing to do
        } else {
            target = address(r);
        }

        // prepare tos and vs arrays with one entry to drive the loop
        address[] memory tos = new address[](1);
        tos[0] = address(this);
        uint[] memory vs = new uint[](1);
        vs[0] = v;

        // Now call transfer and record whether it succeeded (did not revert)
        bool ok;
        try c.transfer(target, tos, vs) {
            ok = true;
        } catch {
            ok = false;
        }

        // General property: the reference contract forbids address(0) as contract_address via modifier
        // so when the external callee would revert, the call must not succeed; we assert that ok == false
        // This single assertion is satisfied by the reference for all inputs, but the mutant that allows
        // address(0) can make ok == true for some inputs (fuzzer will find callee == address(0)).
        assertTrue(!ok);
    }
}

contract Reverter { fallback() external payable { revert(); } }
